{"command":"cd /testbed && python3 -c "
import json
r = json.load(open('revocation_report.json'))
# verify no _comment_ fields remain
def find_comments(o, path=''):
    if isinstance(o, dict):
        for k,v in o.items():
            if k.startswith('_comment'): print('LEFTOVER:', path+'/'+k)
            find_comments(v, path+'/'+k)
    elif isinstance(o, list):
        for i,v in enumerate(o): find_comments(v, f'{path}[{i}]')
find_comments(r)
s = r['summary']
print('summary:', s)
assert s['total_employees_checked'] == len(r['employee_details']) == 10
assert s['total_privileges_checked'] == sum(len(e['privileges']) for e in r['employee_details']) == 30
assert s['successfully_revoked_count'] == sum(1 for e in r['employee_details'] for p in e['privileges'] if p['privilege_revoked']) == 28
print('findings:', r['findings'])
print('OK - no _comment_ fields, counts consistent')
""}

